import sys

def main() -> int:
    valid = 0
    invalid = 0
    total = 0
    for line in open(sys.argv[1]):
        try:
            value = int(line.strip())
        except ValueError:
            invalid += 1
            continue
        total += value
        valid += 1
    print(valid)
    print(invalid)
    print(total)
    return 0

if __name__ == "__main__":
    sys.exit(main())
